CREATE OR REPLACE FUNCTION public.game_add_pending_loot(p_expedition uuid, p_item text, p_qty integer)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  cur bigint;
  owner_id uuid;
  site text;
  site_total bigint;
  site_cap integer;
  add_qty bigint;
begin
  select player_id,site_id into owner_id,site
  from public.game_expeditions
  where id=p_expedition;
  if owner_id is null then return; end if;

  perform pg_advisory_xact_lock(hashtextextended(owner_id::text||':'||site,0));

  select public.game_site_loot_capacity(owner_id,site) into site_cap;

  select coalesce(sum(j.value::bigint),0) into site_total
  from public.game_expeditions ge
  cross join lateral jsonb_each_text(coalesce(ge.pending_loot,'{}'::jsonb)) j(key,value)
  where ge.player_id=owner_id and ge.site_id=site;

  add_qty:=least(
    greatest(0,coalesce(p_qty,0))::bigint,
    greatest(0,site_cap-site_total)
  );
  if add_qty<=0 then return; end if;

  select coalesce((pending_loot->>p_item)::bigint,0) into cur
  from public.game_expeditions
  where id=p_expedition
  for update;

  update public.game_expeditions
  set pending_loot=jsonb_set(
        coalesce(pending_loot,'{}'::jsonb),
        array[p_item],
        to_jsonb(cur+add_qty),
        true
      ),
      updated_at=now()
  where id=p_expedition;
end
$function$

CREATE OR REPLACE FUNCTION public.game_apply_death_xp_penalty(p_monster uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  cur_xp int;
  lost int;
begin
  select xp into cur_xp from public.game_monsters where id=p_monster for update;
  if cur_xp is null then return 0; end if;
  lost:=floor(greatest(0,cur_xp)*0.20)::int;
  if lost>0 then
    update public.game_monsters set xp=greatest(0,cur_xp-lost) where id=p_monster;
  end if;
  return lost;
end
$function$

CREATE OR REPLACE FUNCTION public.game_apply_xp(p_monster uuid, p_amount integer)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  lv int;
  x int;
  needed int;
  cap_level int;
  fam text;
  form text;
  exp_id uuid;
  cur_pending bigint;
  requested_xp int;
  remaining_xp int;
  applied_xp int:=0;
  step_xp int;
begin
  requested_xp:=greatest(0,coalesce(p_amount,0));
  select level,xp,family,form_id into lv,x,fam,form
  from public.game_monsters where id=p_monster for update;
  if lv is null then return; end if;

  select min(required_level) into cap_level
  from public.game_evolution_defs
  where base_family=fam and from_form_id=form;
  cap_level:=coalesce(cap_level,60);

  if lv>=cap_level then
    update public.game_monsters set xp=0 where id=p_monster;
    return;
  end if;

  remaining_xp:=requested_xp;
  while remaining_xp>0 and lv<cap_level loop
    needed:=greatest(1,lv*100);
    if x>=needed then
      x:=x-needed;
      lv:=lv+1;
      continue;
    end if;
    step_xp:=least(remaining_xp,needed-x);
    x:=x+step_xp;
    remaining_xp:=remaining_xp-step_xp;
    applied_xp:=applied_xp+step_xp;
    if x>=needed then
      x:=x-needed;
      lv:=lv+1;
    end if;
  end loop;

  if lv>=cap_level then
    lv:=cap_level;
    x:=0;
  end if;
  update public.game_monsters set level=lv,xp=x where id=p_monster;

  if applied_xp>0 then
    select ge.id into exp_id
    from public.game_expedition_members em
    join public.game_expeditions ge on ge.id=em.expedition_id
    where em.monster_id=p_monster and ge.active=true
    order by ge.started_at desc
    limit 1;

    if exp_id is not null then
      select coalesce((pending_xp->>p_monster::text)::bigint,0)
      into cur_pending
      from public.game_expeditions
      where id=exp_id
      for update;

      update public.game_expeditions
      set pending_xp=jsonb_set(
            coalesce(pending_xp,'{}'::jsonb),
            array[p_monster::text],
            to_jsonb(cur_pending+applied_xp),
            true
          ),
          updated_at=now()
      where id=exp_id;
    end if;
  end if;
end
$function$

CREATE OR REPLACE FUNCTION public.game_cancel_craft(p_job uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  uid uuid:=auth.uid();
  j public.game_craft_jobs%rowtype;
  kv record;
  spent jsonb;
  shifted int:=0;
begin
  if uid is null then raise exception 'unauthorized'; end if;
  perform public.game_process_economy();
  select * into j from public.game_craft_jobs where id=p_job and player_id=uid for update;
  if j.id is null then raise exception 'job_missing'; end if;
  if j.status not in ('running','queued') then raise exception 'job_not_cancelable'; end if;

  spent:=coalesce(j.materials_spent,'{}'::jsonb);
  if spent='{}'::jsonb then
    select coalesce(jsonb_object_agg(k.key,to_jsonb((k.value::bigint*greatest(1,j.batch_qty))::bigint)),'{}'::jsonb)
    into spent
    from public.game_recipes r
    cross join lateral jsonb_each_text(r.inputs) k
    where r.id=j.recipe_id;
  end if;

  for kv in select key,value from jsonb_each_text(spent) loop
    insert into public.game_inventory(player_id,item_id,qty)
    values(uid,kv.key,kv.value::bigint)
    on conflict(player_id,item_id) do update set qty=public.game_inventory.qty+excluded.qty;
  end loop;

  update public.game_craft_jobs
  set status='cancelled',cancelled_at=now(),completed_at=now()
  where id=j.id;
  shifted:=public.game_reflow_craft_queue(uid);
  return jsonb_build_object('type','craft','itemId',j.output_item,'quantity',j.batch_qty,'refunded',spent,'shiftedJobs',shifted);
end
$function$

CREATE OR REPLACE FUNCTION public.game_cancel_sell(p_job uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  uid uuid:=auth.uid();
  j public.game_sell_jobs%rowtype;
  shifted int:=0;
begin
  if uid is null then raise exception 'unauthorized'; end if;
  perform public.game_process_economy();
  select * into j from public.game_sell_jobs where id=p_job and player_id=uid for update;
  if j.id is null then raise exception 'job_missing'; end if;
  if j.status not in ('running','queued') then raise exception 'job_not_cancelable'; end if;

  insert into public.game_inventory(player_id,item_id,qty)
  values(uid,j.item_id,greatest(1,j.quantity))
  on conflict(player_id,item_id) do update set qty=public.game_inventory.qty+excluded.qty;

  update public.game_sell_jobs
  set status='cancelled',cancelled_at=now(),completed_at=now()
  where id=j.id;
  shifted:=public.game_reflow_sell_queue(uid);
  return jsonb_build_object('type','sell','itemId',j.item_id,'quantity',j.quantity,'shiftedJobs',shifted);
end
$function$

CREATE OR REPLACE FUNCTION public.game_claim_craft(p_job uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare j record; v_player uuid; manual_mode boolean;
begin
  v_player:=auth.uid();
  if v_player is null then raise exception 'unauthorized'; end if;
  select manual_economy_claim into manual_mode from public.game_players where device_id=v_player;
  if coalesce(manual_mode,false)=false then raise exception 'manual_mode_disabled'; end if;
  perform public.game_process_economy();
  select * into j from public.game_craft_jobs where id=p_job and player_id=v_player for update;
  if j.id is null then raise exception 'job_missing'; end if;
  if j.status='done' then raise exception 'job_already_claimed'; end if;
  if j.status<>'ready' then raise exception 'job_not_ready'; end if;
  insert into public.game_inventory(player_id,item_id,qty)
  values(j.player_id,j.output_item,j.output_qty)
  on conflict(player_id,item_id) do update set qty=public.game_inventory.qty+excluded.qty;
  update public.game_craft_jobs set status='done' where id=j.id;
  return jsonb_build_object('jobId',j.id,'itemId',j.output_item,'quantity',j.output_qty);
end
$function$

CREATE OR REPLACE FUNCTION public.game_claim_craft(p_player uuid, p_job uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare j record;
begin
  perform public.game_process_economy();
  select * into j
  from public.game_craft_jobs
  where id=p_job and player_id=p_player
  for update;
  if j.id is null then raise exception 'job_missing'; end if;
  if j.status='done' then raise exception 'job_already_claimed'; end if;
  if j.status<>'ready' then raise exception 'job_not_ready'; end if;

  insert into public.game_inventory(player_id,item_id,qty)
  values(j.player_id,j.output_item,j.output_qty)
  on conflict(player_id,item_id) do update
    set qty=public.game_inventory.qty+excluded.qty;

  update public.game_craft_jobs set status='done' where id=j.id;
  return jsonb_build_object('jobId',j.id,'itemId',j.output_item,'quantity',j.output_qty);
end
$function$

CREATE OR REPLACE FUNCTION public.game_claim_sell(p_job uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare j record; v_player uuid; manual_mode boolean;
begin
  v_player:=auth.uid();
  if v_player is null then raise exception 'unauthorized'; end if;
  select manual_economy_claim into manual_mode from public.game_players where device_id=v_player;
  if coalesce(manual_mode,false)=false then raise exception 'manual_mode_disabled'; end if;
  perform public.game_process_economy();
  select * into j from public.game_sell_jobs where id=p_job and player_id=v_player for update;
  if j.id is null then raise exception 'job_missing'; end if;
  if j.status='done' then raise exception 'job_already_claimed'; end if;
