CREATE OR REPLACE FUNCTION public.game_release_monster(p_player uuid, p_monster uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
 m public.game_monsters%rowtype;
 gear_count int:=0;
begin
 perform 1 from public.game_players where device_id=p_player for update;
 if not found then raise exception 'player_missing'; end if;
 select * into m from public.game_monsters where id=p_monster and player_id=p_player and released_at is null for update;
 if m.id is null then raise exception 'monster_missing'; end if;
 if exists(select 1 from public.game_expedition_members em join public.game_expeditions ge on ge.id=em.expedition_id where em.monster_id=m.id and ge.active=true) then raise exception 'monster_busy'; end if;

 select count(*) into gear_count from public.game_monster_equipment q where q.player_id=p_player and q.monster_id=m.id;
 insert into public.game_inventory(player_id,item_id,qty)
 select p_player,q.item_id,count(*)::bigint from public.game_monster_equipment q
 where q.player_id=p_player and q.monster_id=m.id and coalesce(q.enhance_level,0)=0 group by q.item_id
 on conflict(player_id,item_id) do update set qty=public.game_inventory.qty+excluded.qty;
 insert into public.game_enhanced_inventory(player_id,item_id,enhance_level,qty)
 select p_player,q.item_id,q.enhance_level,count(*)::bigint from public.game_monster_equipment q
 where q.player_id=p_player and q.monster_id=m.id and q.enhance_level>0 group by q.item_id,q.enhance_level
 on conflict(player_id,item_id,enhance_level) do update set qty=public.game_enhanced_inventory.qty+excluded.qty,updated_at=now();
 delete from public.game_monster_equipment where player_id=p_player and monster_id=m.id;
 update public.game_expeditions set pending_xp=coalesce(pending_xp,'{}'::jsonb)-m.id::text,updated_at=now() where player_id=p_player and coalesce(pending_xp,'{}'::jsonb) ? m.id::text;
 update public.game_monsters set released_at=now() where id=m.id;
 return jsonb_build_object('monsterId',m.id,'name',m.name,'released',true,'gearReturned',gear_count);
end $function$

CREATE OR REPLACE FUNCTION public.game_restart_expedition(p_expedition uuid, p_monsters uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
 uid uuid := auth.uid(); old public.game_expeditions%rowtype; fresh public.game_expeditions%rowtype;
 count_ids integer; valid_ids integer; new_members jsonb; previous_members uuid[];
BEGIN
 IF uid IS NULL THEN RAISE EXCEPTION 'unauthorized'; END IF;
 count_ids := coalesce(cardinality(p_monsters),0);
 IF count_ids < 1 OR count_ids > 4 OR (SELECT count(DISTINCT x) FROM unnest(p_monsters) x) <> count_ids THEN RAISE EXCEPTION 'party_size'; END IF;
 -- Same order as cron: global tick lock, then rows. No network work inside this lock.
 PERFORM pg_advisory_xact_lock(hashtextextended('game_tick_all',0));
 SELECT * INTO old FROM public.game_expeditions WHERE id=p_expedition AND player_id=uid FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'invalid_target'; END IF;
 IF NOT old.active THEN RAISE EXCEPTION 'expedition_changed'; END IF;
 PERFORM 1 FROM public.game_monsters WHERE player_id=uid AND id=ANY(p_monsters) ORDER BY id FOR UPDATE;
 SELECT count(*) INTO valid_ids FROM public.game_monsters WHERE player_id=uid AND id=ANY(p_monsters) AND released_at IS NULL;
 IF valid_ids <> count_ids THEN RAISE EXCEPTION 'monster_missing'; END IF;
 IF EXISTS(SELECT 1 FROM public.game_expeditions e JOIN public.game_expedition_members m ON m.expedition_id=e.id WHERE e.active AND e.id<>old.id AND m.monster_id=ANY(p_monsters)) THEN RAISE EXCEPTION 'monster_busy'; END IF;
 SELECT array_agg(monster_id ORDER BY position) INTO previous_members FROM public.game_expedition_members WHERE expedition_id=old.id;
 IF previous_members = p_monsters THEN RAISE EXCEPTION 'party_unchanged'; END IF;
 UPDATE public.game_expeditions SET active=false,phase='파티 재편 · 복귀',battle_state=battle_state||jsonb_build_object('active',false,'result','cancelled','turn',null),event_state=jsonb_build_object('type','reconfigure','text','파티 재편으로 현재 전투를 취소했습니다','t',now()),updated_at=now() WHERE id=old.id;
 INSERT INTO public.game_expeditions(player_id,monster_id,site_id,active,phase,event_state)
 VALUES(uid,p_monsters[1],old.site_id,true,'탐색',jsonb_build_object('type','deploy','text',count_ids||'인 박멸조 재편 · 탐험 재시작','t',now())) RETURNING * INTO fresh;
 INSERT INTO public.game_expedition_members(expedition_id,player_id,monster_id,position)
 SELECT fresh.id,uid,v.id,v.ord::integer FROM unnest(p_monsters) WITH ORDINALITY v(id,ord);
 SELECT coalesce(jsonb_agg(to_jsonb(m) ORDER BY position),'[]'::jsonb) INTO new_members FROM public.game_expedition_members m WHERE expedition_id=fresh.id;
 RETURN jsonb_build_object('expeditionId',fresh.id,'previousExpeditionId',old.id,'expedition',to_jsonb(fresh),'members',new_members);
END $function$

CREATE OR REPLACE FUNCTION public.game_rewrite_chapter_event_text()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  t text;
  enemy_name text;
  result_name text;
  phase_type text;
begin
  if new.event_state is distinct from old.event_state then
    t:=coalesce(new.event_state->>'type','');
    enemy_name:=new.event_state->>'enemy';
    result_name:=new.event_state->>'result';
    if t in ('search','rest','track','battle') then
      new.event_state:=jsonb_set(coalesce(new.event_state,'{}'::jsonb),'{text}',to_jsonb(public.game_chapter_event_text(new.site_id,t,enemy_name,result_name)),true);
    end if;
  end if;

  if new.battle_log is distinct from old.battle_log and jsonb_typeof(new.battle_log)='array' and jsonb_array_length(new.battle_log)>0 then
    if coalesce(new.battle_log->0->>'type','')='explore' then
      phase_type:=case new.battle_log->0->>'phase' when '수색' then 'search' when '휴식' then 'rest' else 'track' end;
      new.battle_log:=jsonb_set(new.battle_log,'{0,event}',to_jsonb(public.game_chapter_event_text(new.site_id,phase_type,null,null)),true);
    end if;
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.game_roll_exploration_recovery(p_expedition uuid, p_state jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  st jsonb:=coalesce(p_state,'{}'::jsonb);
  hp jsonb:=coalesce(st->'partyHp','{}'::jsonb);
  mx jsonb:=coalesce(st->'partyMaxHp','{}'::jsonb);
  k text;
  v text;
  cur_hp int;
  max_hp int;
  add_hp int;
  total_heal int:=0;
  alive_n int:=0;
  damaged_n int:=0;
  avg_ratio numeric:=1;
  ratio_sum numeric:=0;
  recover_chance numeric:=0;
  roll numeric;
  mode text:='none';
  msg text:='';
  target_key text;
  target_ratio numeric:=2;
begin
  if jsonb_typeof(hp)<>'object' or jsonb_typeof(mx)<>'object' then
    return jsonb_build_object('state',st,'heal',0,'kind','none','text','');
  end if;

  for k,v in select key,value from jsonb_each_text(mx) loop
    max_hp:=greatest(1,v::int);
    cur_hp:=coalesce((hp->>k)::int,max_hp);
    if cur_hp>0 then
      alive_n:=alive_n+1;
      ratio_sum:=ratio_sum+least(1,cur_hp::numeric/max_hp);
      if cur_hp<max_hp then damaged_n:=damaged_n+1; end if;
    end if;
  end loop;
  if alive_n=0 or damaged_n=0 then
    return jsonb_build_object('state',st,'heal',0,'kind','none','text','');
  end if;

  avg_ratio:=ratio_sum/alive_n;
  recover_chance:=case when avg_ratio<0.35 then 0.90 when avg_ratio<0.60 then 0.72 else 0.50 end;
  if random()>=recover_chance then
    return jsonb_build_object('state',st,'heal',0,'kind','none','text','');
  end if;

  roll:=random();
  if roll<0.25 then
    mode:='well';
    for k,v in select key,value from jsonb_each_text(mx) loop
      max_hp:=greatest(1,v::int);cur_hp:=coalesce((hp->>k)::int,max_hp);
      if cur_hp>0 and cur_hp<max_hp then
        add_hp:=least(max_hp-cur_hp,greatest(1,round(max_hp*0.42)::int));
        hp:=jsonb_set(hp,array[k],to_jsonb(cur_hp+add_hp),true);total_heal:=total_heal+add_hp;
      end if;
    end loop;
    msg:='낡은 우물을 발견해 물을 마셨다 · 체력 +'||total_heal;
  elsif roll<0.65 then
    mode:='potion';target_key:=null;target_ratio:=2;
    for k,v in select key,value from jsonb_each_text(mx) loop
      max_hp:=greatest(1,v::int);cur_hp:=coalesce((hp->>k)::int,max_hp);
      if cur_hp>0 and cur_hp<max_hp and cur_hp::numeric/max_hp<target_ratio then target_ratio:=cur_hp::numeric/max_hp;target_key:=k;end if;
    end loop;
    if target_key is not null then
      max_hp:=greatest(1,(mx->>target_key)::int);cur_hp:=coalesce((hp->>target_key)::int,max_hp);
      add_hp:=least(max_hp-cur_hp,greatest(1,round(max_hp*0.58)::int));
      hp:=jsonb_set(hp,array[target_key],to_jsonb(cur_hp+add_hp),true);total_heal:=add_hp;
      msg:='용사에게서 빼앗은 회복약을 사용했다 · 체력 +'||total_heal;
    end if;
  else
    mode:='camp';
    for k,v in select key,value from jsonb_each_text(mx) loop
      max_hp:=greatest(1,v::int);cur_hp:=coalesce((hp->>k)::int,max_hp);
      if cur_hp>0 and cur_hp<max_hp then
        add_hp:=least(max_hp-cur_hp,greatest(1,round(max_hp*0.22)::int));
        hp:=jsonb_set(hp,array[k],to_jsonb(cur_hp+add_hp),true);total_heal:=total_heal+add_hp;
      end if;
    end loop;
    msg:='버려진 야영지에서 약초와 식량을 챙겼다 · 체력 +'||total_heal;
  end if;

  st:=st||jsonb_build_object('active',false,'partyHp',hp,'partyMaxHp',mx,'recovery',jsonb_build_object('kind',mode,'heal',total_heal,'t',now()));
  return jsonb_build_object('state',st,'heal',total_heal,'kind',mode,'text',msg);
end
$function$

CREATE OR REPLACE FUNCTION public.game_set_candidate_lock(p_player uuid, p_candidate uuid, p_locked boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare dummy uuid;
begin
 select device_id into dummy from public.game_players where device_id=p_player for update;
 if not found then raise exception 'player_missing'; end if;
 update public.game_candidates set is_locked=coalesce(p_locked,false) where id=p_candidate and player_id=p_player;
 if not found then raise exception 'candidate_missing'; end if;
 return coalesce(p_locked,false);
end
$function$

CREATE OR REPLACE FUNCTION public.game_set_monster_detail_defaults()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if new.family='slime' then new.hp_base:=150; new.atk_base:=15; new.def_base:=11; new.spd_base:=8; new.crit_base:=0.04; new.evade_base:=0.03;
  elsif new.family='goblin' then new.hp_base:=105; new.atk_base:=21; new.def_base:=7; new.spd_base:=15; new.crit_base:=0.08; new.evade_base:=0.07;
  elsif new.family='troll' then new.hp_base:=215; new.atk_base:=25; new.def_base:=15; new.spd_base:=6; new.crit_base:=0.05; new.evade_base:=0.02;
  end if;
  new.growth_grade:=case when new.talent>=95 then 'S' when new.talent>=90 then 'A' when new.talent>=84 then 'B' else 'C' end;
  if new.personality is null or new.personality='침착' then
    new.personality:=case abs(hashtext(coalesce(new.name,''))) % 6 when 0 then '겁쟁이' when 1 then '광전사' when 2 then '약탈광' when 3 then '인간혐오' when 4 then '야행성' else '침착' end;
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.game_spawn_candidates()
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare p record;i int;r numeric;grade text;fam text;pers text;tr text;talent int;mult numeric;hp int;atk int;de int;spd int;cr numeric;ev numeric;pb int;made int:=0;batch_count int;locked_count int;new_count int;
begin
 for p in select * from public.game_players where next_candidate_at<=now() for update skip locked loop
  delete from public.game_candidates where player_id=p.device_id and not coalesce(is_locked,false);batch_count:=greatest(4,coalesce(p.tavern_level,1)+3);select count(*)::int into locked_count from public.game_candidates where player_id=p.device_id and coalesce(is_locked,false);new_count:=greatest(0,batch_count-locked_count);
  if new_count>0 then for i in 1..new_count loop
   r:=random();grade:=case when p.tavern_level<=1 then case when r<0.65 then 'C' when r<0.95 then 'B' else 'A' end when p.tavern_level=2 then case when r<0.45 then 'C' when r<0.85 then 'B' when r<0.99 then 'A' else 'S' end when p.tavern_level=3 then case when r<0.25 then 'C' when r<0.70 then 'B' when r<0.97 then 'A' else 'S' end when p.tavern_level=4 then case when r<0.10 then 'C' when r<0.50 then 'B' when r<0.93 then 'A' else 'S' end else case when r<0.35 then 'B' when r<0.85 then 'A' else 'S' end end;
   fam:=(array['slime','goblin','troll','mandrake','imp','golem'])[1+floor(random()*6)::int];pers:=(array['침착','약탈광','광전사','겁쟁이','인간혐오','야행성'])[1+floor(random()*6)::int];tr:=(array['질긴 가죽','야성','재빠름','수집광','학습 본능'])[1+floor(random()*5)::int];talent:=case grade when 'S' then 94+floor(random()*7)::int when 'A' then 88+floor(random()*10)::int when 'B' then 82+floor(random()*11)::int else 76+floor(random()*12)::int end;talent:=least(100,talent+greatest(0,p.tavern_level-1));mult:=case grade when 'S' then 1.16 when 'A' then 1.10 when 'B' then 1.05 else 1 end;
   if fam='slime' then hp:=round(145*mult);atk:=round(15*mult);de:=round(11*mult);spd:=round(9*mult);cr:=0.04;ev:=0.03;pb:=45;
   elsif fam='goblin' then hp:=round(100*mult);atk:=round(21*mult);de:=round(7*mult);spd:=round(14*mult);cr:=0.08;ev:=0.06;pb:=52;
   elsif fam='troll' then hp:=round(175*mult);atk:=round(24*mult);de:=round(13*mult);spd:=round(7*mult);cr:=0.05;ev:=0.02;pb:=68;
   elsif fam='mandrake' then hp:=round(125*mult);atk:=round(12*mult);de:=round(9*mult);spd:=round(10*mult);cr:=0.03;ev:=0.04;pb:=50;
   elsif fam='imp' then hp:=round(86*mult);atk:=round(22*mult);de:=round(5*mult);spd:=round(11*mult);cr:=0.06;ev:=0.04;pb:=54;
   else hp:=round(240*mult);atk:=round(13*mult);de:=round(21*mult);spd:=round(5*mult);cr:=0.02;ev:=0.01;pb:=63;end if;
   insert into public.game_candidates(player_id,name,family,talent,trait,power_base,personality,growth_grade,hp_base,atk_base,def_base,spd_base,crit_base,evade_base,is_locked)
   values(p.device_id,(array['꾸륵','찍찍','우르그','푸르','크룩','도르','무그','벨칵','루트','지직','둔석','모스'])[1+floor(random()*12)::int],fam,talent,tr,pb,pers,grade,hp,atk,de,spd,cr,ev,false);made:=made+1;
  end loop;end if;update public.game_players set next_candidate_at=now()+interval '4 hours',updated_at=now() where device_id=p.device_id;
 end loop;return made;
end $function$

CREATE OR REPLACE FUNCTION public.game_start_craft(p_player uuid, p_recipe text, p_qty integer)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  r record;
  kv record;
  have bigint;
  queued_count int;
  queue_cap int;
  job_id uuid;
  scheduled_start timestamptz;
  scheduled_finish timestamptz;
  total_need bigint;
  spend jsonb:='{}'::jsonb;
begin
  perform public.game_process_economy();
  if coalesce(p_qty,0)<1 then raise exception 'quantity_invalid'; end if;
  select * into r from public.game_recipes where id=p_recipe;
  if r.id is null then raise exception 'recipe_missing'; end if;

  select greatest(5,coalesce(workshop_level,1)+4) into queue_cap
  from public.game_players where device_id=p_player;
  select count(*) into queued_count
  from public.game_craft_jobs where player_id=p_player and status in ('running','queued');
  if queued_count>=queue_cap then raise exception 'craft_queue_full'; end if;

  select coalesce(jsonb_object_agg(k.key,to_jsonb((k.value::bigint*p_qty::bigint)::bigint)),'{}'::jsonb)
  into spend from jsonb_each_text(r.inputs) k;

  for kv in select key,value from jsonb_each_text(spend) loop
    select coalesce(qty,0) into have from public.game_inventory where player_id=p_player and item_id=kv.key;
    if coalesce(have,0)<kv.value::bigint then raise exception 'material_short'; end if;
  end loop;

  for kv in select key,value from jsonb_each_text(spend) loop
    update public.game_inventory set qty=qty-kv.value::bigint where player_id=p_player and item_id=kv.key;
    delete from public.game_inventory where player_id=p_player and item_id=kv.key and qty<=0;
  end loop;

  select greatest(now(),coalesce(max(finish_at),now())) into scheduled_start
  from public.game_craft_jobs where player_id=p_player and status in ('running','queued');
  scheduled_finish:=scheduled_start+make_interval(secs=>r.craft_seconds*p_qty);

  insert into public.game_craft_jobs(player_id,recipe_id,output_item,output_qty,batch_qty,started_at,finish_at,status,materials_spent)
  values(p_player,r.id,r.output_item,r.output_qty*p_qty,p_qty,scheduled_start,scheduled_finish,
         case when scheduled_start<=now() then 'running' else 'queued' end,spend)
  returning id into job_id;
  return job_id;
end
$function$

CREATE OR REPLACE FUNCTION public.game_start_sell(p_player uuid, p_item text, p_qty integer)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare r record; d record; have bigint; queued_count int; queue_cap int; job_id uuid; unit_price int; unit_seconds int; scheduled_start timestamptz; scheduled_finish timestamptz;
begin
 perform public.game_process_economy(); if coalesce(p_qty,0)<1 then raise exception 'quantity_invalid'; end if;
 select * into r from public.game_recipes where output_item=p_item order by sort_order limit 1; if r.id is not null then unit_price:=r.sale_gold;unit_seconds:=greatest(1,ceil(r.craft_seconds/1.2)::integer); else select * into d from public.game_item_defs where id=p_item and kind='material' and sale_gold>0 limit 1; if d.id is null then raise exception 'not_sellable';end if;unit_price:=d.sale_gold;unit_seconds:=greatest(1,d.sell_seconds);end if;
 select greatest(5,coalesce(shop_level,1)+4) into queue_cap from public.game_players where device_id=p_player; select count(*) into queued_count from public.game_sell_jobs where player_id=p_player and status in ('running','queued'); if queued_count>=queue_cap then raise exception 'sell_queue_full'; end if;
 select coalesce(qty,0) into have from public.game_inventory where player_id=p_player and item_id=p_item; if coalesce(have,0)<p_qty then raise exception 'item_missing'; end if; update public.game_inventory set qty=qty-p_qty where player_id=p_player and item_id=p_item; delete from public.game_inventory where player_id=p_player and item_id=p_item and qty<=0;
 select greatest(now(),coalesce(max(finish_at),now())) into scheduled_start from public.game_sell_jobs where player_id=p_player and status in ('running','queued'); scheduled_finish:=scheduled_start+make_interval(secs=>unit_seconds*p_qty);
 insert into public.game_sell_jobs(player_id,item_id,sale_gold,quantity,started_at,finish_at,status) values(p_player,p_item,unit_price*p_qty,p_qty,scheduled_start,scheduled_finish,case when scheduled_start<=now() then 'running' else 'queued' end) returning id into job_id; return job_id;
end $function$

CREATE OR REPLACE FUNCTION public.game_tick_all()
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare n integer:=0;
begin
  /* Browser state polls and cron can collide. Only one global tick should do work;
     everyone else returns immediately and reads the latest committed state. */
  if not pg_try_advisory_xact_lock(hashtextextended('game_tick_all',0)) then
    return 0;
  end if;
  n:=n+public.game_process_economy();
  n:=n+public.game_spawn_candidates();
  n:=n+public.game_process_expeditions();
  return n;
end
$function$

CREATE OR REPLACE FUNCTION public.game_trigger_monster_skill(p_monster uuid, p_attack_count integer, p_hp_ratio numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare r record; fired boolean:=false;
begin
 select m.id monster_id,m.name owner_name,s.* into r from public.game_monsters m join public.game_skill_defs s on s.id=m.skill_id where m.id=p_monster;
 if not found then return '{}'::jsonb; end if;
 fired:=case r.trigger_type when 'chance' then random()<r.trigger_value when 'every_n' then r.trigger_count>0 and mod(greatest(1,p_attack_count),r.trigger_count)=0 when 'hp_below_chance' then p_hp_ratio<=r.condition_value and random()<r.trigger_value else false end;
 if not fired then return '{}'::jsonb; end if;
 return jsonb_build_object('id',r.id,'name',r.name,'owner',r.owner_name,'monsterId',r.monster_id,'damage_multiplier',r.damage_multiplier,'defense_ignore',r.defense_ignore,'effect_type',r.effect_type,'heal_ratio',r.heal_ratio,'damage_reduction',r.damage_reduction,'taunt_weight',r.taunt_weight);
end $function$

CREATE OR REPLACE FUNCTION public.game_unequip_item(p_player uuid, p_monster uuid, p_slot text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare v_old text;v_level integer:=0;
begin
  if p_slot not in ('weapon','armor','accessory') then raise exception 'invalid_slot'; end if;
  select item_id,enhance_level into v_old,v_level from public.game_monster_equipment where monster_id=p_monster and player_id=p_player and slot=p_slot for update;
  if v_old is null then return true; end if;
  delete from public.game_monster_equipment where monster_id=p_monster and player_id=p_player and slot=p_slot;
  if coalesce(v_level,0)>0 then
    insert into public.game_enhanced_inventory(player_id,item_id,enhance_level,qty) values(p_player,v_old,v_level,1)
    on conflict(player_id,item_id,enhance_level) do update set qty=public.game_enhanced_inventory.qty+1,updated_at=now();
  else
    insert into public.game_inventory(player_id,item_id,qty) values(p_player,v_old,1)
    on conflict(player_id,item_id) do update set qty=public.game_inventory.qty+1;
  end if;
  return true;
end $function$
